BEGIN;
PRAGMA writable_schema = on;
PRAGMA encoding = 'UTF-8';
PRAGMA page_size = '4096';
PRAGMA auto_vacuum = '0';
PRAGMA user_version = '4';
PRAGMA application_id = '0';
CREATE TABLE sqlite_sequence(name,seq);
CREATE TABLE products (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL UNIQUE,
            price REAL NOT NULL,
            category TEXT DEFAULT 'عام',
            image TEXT,
            stock INTEGER NOT NULL DEFAULT 0,
            cost REAL DEFAULT 0,
            barcode TEXT,
            supplier_id INTEGER,
            is_service INTEGER DEFAULT 0,
            unit TEXT DEFAULT 'وحدة'
        , min_stock_level REAL DEFAULT 0, bulk_unit_name TEXT, bulk_unit_size REAL DEFAULT 1, metadata_json TEXT, sync_id TEXT, updated_at INTEGER, is_deleted INTEGER DEFAULT 0, origin_node_id TEXT, node_id TEXT, tax_category TEXT DEFAULT 'S', label_template_id TEXT, expiry_date TEXT, batch_number TEXT, net_weight_g REAL, country_of_origin TEXT, is_active INTEGER DEFAULT 1, sort_order INTEGER DEFAULT 0, is_divisible INTEGER DEFAULT 0, sub_unit_name TEXT DEFAULT '', pieces_per_unit REAL DEFAULT 1);
CREATE TABLE modifiers (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            product_id INTEGER,
            name TEXT NOT NULL,
            price REAL NOT NULL DEFAULT 0,
            FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE CASCADE
        );
CREATE TABLE sales (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            invoice TEXT UNIQUE NOT NULL,
            timestamp DATETIME DEFAULT CURRENT_TIMESTAMP,
            total_amount REAL NOT NULL,
            subtotal REAL DEFAULT 0,
            tax_amount REAL DEFAULT 0,
            discount REAL DEFAULT 0,
            payment_method TEXT,
            paid REAL,
            change_amount REAL,
            payment_details_json TEXT,
            status TEXT DEFAULT 'paid',
            order_type TEXT DEFAULT 'counter',
            note TEXT,
            uuid TEXT,
            hash TEXT,
            hash_chain TEXT,
            zatca_status TEXT DEFAULT 'pending',
            customer_id INTEGER,
            staff_id INTEGER
        , loyalty_points_redeemed INTEGER DEFAULT 0, sync_id TEXT, updated_at INTEGER, is_deleted INTEGER DEFAULT 0, origin_node_id TEXT, node_id TEXT, discount_type TEXT DEFAULT 'normal', is_agreed_total INTEGER DEFAULT 0, icv INTEGER, zatca_clearance_status TEXT, zatca_cleared_at TEXT, customer_name_snapshot TEXT, customer_tax_id_snapshot TEXT, payment_method_corrected INTEGER DEFAULT 0, sponsor_id INTEGER, beneficiary_name TEXT, voucher_ref TEXT, voucher_discount REAL DEFAULT 0);
CREATE TABLE sales_items (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            sale_id INTEGER,
            product_id INTEGER,
            item_name TEXT NOT NULL,
            item_price REAL NOT NULL,
            quantity INTEGER NOT NULL,
            item_note TEXT,
            modifiers_json TEXT, sync_id TEXT, updated_at INTEGER, is_deleted INTEGER DEFAULT 0, origin_node_id TEXT, sale_sync_id TEXT, node_id TEXT,
            FOREIGN KEY (sale_id) REFERENCES sales(id) ON DELETE CASCADE
        );
CREATE TABLE expenditures (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            description TEXT NOT NULL,
            amount REAL NOT NULL,
            net_amount REAL DEFAULT 0,
            vat_amount REAL DEFAULT 0,
            vat_eligible INTEGER DEFAULT 0,
            category TEXT DEFAULT 'أخرى',
            supplier_name TEXT,
            invoice_ref TEXT,
            expense_date DATE,
            timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
        , status TEXT DEFAULT 'active', sync_id TEXT, updated_at INTEGER, is_deleted INTEGER DEFAULT 0, origin_node_id TEXT, node_id TEXT);
CREATE TABLE shifts (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            opened_at DATETIME DEFAULT CURRENT_TIMESTAMP,
            closed_at DATETIME,
            starting_cash REAL DEFAULT 0,
            actual_cash REAL DEFAULT 0,
            expected_cash REAL DEFAULT 0,
            cash_sales REAL DEFAULT 0,
            card_sales REAL DEFAULT 0,
            status TEXT DEFAULT 'open',
            staff_id INTEGER
        , sync_id TEXT, updated_at INTEGER, is_deleted INTEGER DEFAULT 0, origin_node_id TEXT, node_id TEXT);
CREATE TABLE accounts (
            account_code INTEGER PRIMARY KEY,
            name_ar TEXT NOT NULL,
            type TEXT CHECK(type IN ('Asset','Liability','Equity','Revenue','Expense')),
            parent_id INTEGER,
            balance REAL DEFAULT 0, level INTEGER DEFAULT 1, normal_balance TEXT DEFAULT 'debit', is_system INTEGER DEFAULT 0, is_active INTEGER DEFAULT 1, name_en TEXT, created_by INTEGER DEFAULT 1,
            FOREIGN KEY (parent_id) REFERENCES accounts(account_code)
        );
CREATE TABLE ledger_entries (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            account_code INTEGER,
            date DATETIME DEFAULT CURRENT_TIMESTAMP,
            description TEXT,
            debit REAL DEFAULT 0,
            credit REAL DEFAULT 0,
            reference TEXT, sync_id TEXT, updated_at INTEGER, is_deleted INTEGER DEFAULT 0, origin_node_id TEXT, node_id TEXT,
            FOREIGN KEY (account_code) REFERENCES accounts(account_code)
        );
CREATE TABLE customers (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            phone TEXT,
            email TEXT,
            address TEXT,
            tax_id TEXT,
            loyalty_points INTEGER DEFAULT 0,
            tier TEXT DEFAULT 'bronze',
            total_spent REAL DEFAULT 0,
            created_at DATETIME DEFAULT CURRENT_TIMESTAMP
        , last_whatsapp_sent DATETIME, na_short TEXT, na_building TEXT, na_street TEXT, na_secondary TEXT, na_district TEXT, na_postal TEXT, na_city TEXT, na_country TEXT, id_type TEXT, id_value TEXT, sync_id TEXT, updated_at INTEGER, is_deleted INTEGER DEFAULT 0, origin_node_id TEXT, node_id TEXT, credit_limit REAL DEFAULT NULL, outstanding_balance REAL DEFAULT 0, tags TEXT, notes TEXT, last_visit DATETIME, visit_count INTEGER DEFAULT 0);
CREATE TABLE staff (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            pin TEXT NOT NULL UNIQUE,
            role TEXT DEFAULT 'Cashier',
            permissions_json TEXT DEFAULT '[]',
            created_at DATETIME DEFAULT CURRENT_TIMESTAMP
        , sync_id TEXT, updated_at INTEGER, is_deleted INTEGER DEFAULT 0, origin_node_id TEXT, salt TEXT, failed_attempts INTEGER DEFAULT 0, locked_until INTEGER DEFAULT 0, node_id TEXT);
CREATE TABLE suppliers (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL UNIQUE,
            contact_person TEXT,
            phone TEXT,
            email TEXT,
            tax_id TEXT,
            address TEXT,
            created_at DATETIME DEFAULT CURRENT_TIMESTAMP
        , na_short TEXT, na_building TEXT, na_street TEXT, na_secondary TEXT, na_district TEXT, na_postal TEXT, na_city TEXT, na_country TEXT, id_type TEXT, id_value TEXT, sync_id TEXT, updated_at INTEGER, is_deleted INTEGER DEFAULT 0, origin_node_id TEXT, node_id TEXT);
CREATE TABLE audit_logs (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER,
            action TEXT NOT NULL,
            details TEXT,
            timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
        , user_name TEXT, entity_type TEXT, entity_id TEXT, entity_reference TEXT, field_name TEXT, old_value TEXT, new_value TEXT, ip_address TEXT, session_id TEXT);
CREATE TABLE held_orders (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            label TEXT,
            items_json TEXT NOT NULL,
            customer_id INTEGER,
            table_id INTEGER,
            order_type TEXT DEFAULT 'counter',
            kds_status TEXT DEFAULT 'pending',
            note TEXT,
            created_at DATETIME DEFAULT CURRENT_TIMESTAMP
        , sync_id TEXT, updated_at INTEGER, is_deleted INTEGER DEFAULT 0, origin_node_id TEXT, node_id TEXT);
CREATE TABLE restaurant_tables (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL UNIQUE,
            zone TEXT DEFAULT 'Main',
            capacity INTEGER DEFAULT 4,
            status TEXT DEFAULT 'available',
            x_pos REAL DEFAULT 0,
            y_pos REAL DEFAULT 0,
            current_order_id INTEGER,
            FOREIGN KEY (current_order_id) REFERENCES held_orders(id)
        );
CREATE TABLE stock_history (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            product_id INTEGER,
            change_amount REAL NOT NULL,
            reason TEXT NOT NULL, -- 'sale', 'purchase', 'adjustment', 'return'
            reference_id TEXT,    -- invoice number or purchase ID
            timestamp DATETIME DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE CASCADE
        );
CREATE TABLE purchase_orders (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            supplier_id INTEGER,
            total_amount REAL NOT NULL,
            status TEXT DEFAULT 'pending', -- 'pending', 'received'
            note TEXT,
            received_at DATETIME,
            created_at DATETIME DEFAULT CURRENT_TIMESTAMP, vat_included INTEGER DEFAULT 1, vat_amount REAL DEFAULT 0, sync_id TEXT, updated_at INTEGER, is_deleted INTEGER DEFAULT 0, origin_node_id TEXT, node_id TEXT, paid_amount REAL DEFAULT 0, payment_status TEXT DEFAULT 'unpaid',
            FOREIGN KEY (supplier_id) REFERENCES suppliers(id)
        );
CREATE TABLE purchase_items (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            purchase_id INTEGER,
            product_id INTEGER,
            quantity REAL NOT NULL,
            unit_cost REAL NOT NULL,
            is_bulk INTEGER DEFAULT 0, sync_id TEXT, updated_at INTEGER, is_deleted INTEGER DEFAULT 0, origin_node_id TEXT, purchase_sync_id TEXT, received_quantity REAL DEFAULT 0, node_id TEXT, unit_name TEXT, pieces_per_unit REAL DEFAULT 1,
            FOREIGN KEY (purchase_id) REFERENCES purchase_orders(id) ON DELETE CASCADE,
            FOREIGN KEY (product_id) REFERENCES products(id)
        );
CREATE TABLE promotions (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        name TEXT NOT NULL,
        type TEXT NOT NULL, -- 'BOGO', 'BULK', 'TOTAL'
        buy_product_id INTEGER,
        buy_qty REAL,
        get_product_id INTEGER,
        get_qty REAL,
        discount_value REAL, -- fixed or percentage
        discount_type TEXT, -- 'fixed' or 'pct'
        min_spend REAL,
        active INTEGER DEFAULT 1,
        start_date TEXT,
        end_date TEXT
      );
CREATE TABLE business_settings (
            key TEXT PRIMARY KEY,
            value TEXT
        , zatca_queue_halted INTEGER DEFAULT 0);
CREATE TABLE sync_nodes (
            node_id TEXT PRIMARY KEY,
            name TEXT,
            role TEXT,
            created_at INTEGER
        );
CREATE TABLE sync_watermarks (
            node_id TEXT PRIMARY KEY,
            last_sync_timestamp INTEGER,
            FOREIGN KEY (node_id) REFERENCES sync_nodes(node_id)
        );
CREATE TABLE journal_entries (
            id              INTEGER PRIMARY KEY AUTOINCREMENT,
            entry_date      TEXT    NOT NULL,
            reference_no    TEXT    NOT NULL,
            description     TEXT    NOT NULL,
            entry_type      TEXT    NOT NULL DEFAULT 'Manual',
            reference_type  TEXT,
            reference_id    TEXT,
            status          TEXT    NOT NULL DEFAULT 'posted',
            notes           TEXT,
            attachment_path TEXT,
            created_at      TEXT    NOT NULL DEFAULT (datetime('now')),
            created_by      INTEGER NOT NULL DEFAULT 1
        );
CREATE TABLE journal_entry_lines (
            id              INTEGER PRIMARY KEY AUTOINCREMENT,
            entry_id        INTEGER NOT NULL,
            account_code    INTEGER NOT NULL,
            description     TEXT,
            debit_halala    INTEGER NOT NULL DEFAULT 0,
            credit_halala   INTEGER NOT NULL DEFAULT 0,
            cost_centre_id  INTEGER,
            FOREIGN KEY (entry_id)     REFERENCES journal_entries(id) ON DELETE CASCADE,
            FOREIGN KEY (account_code) REFERENCES accounts(account_code)
        );
CREATE TABLE opening_balance_entries (
            id              INTEGER PRIMARY KEY AUTOINCREMENT,
            journal_entry_id INTEGER NOT NULL,
            opening_date    TEXT    NOT NULL,
            locked          INTEGER NOT NULL DEFAULT 1,
            created_at      TEXT    NOT NULL DEFAULT (datetime('now'))
        );
CREATE TABLE accounting_periods (
            id          INTEGER PRIMARY KEY AUTOINCREMENT,
            period_name TEXT    NOT NULL,
            start_date  TEXT    NOT NULL,
            end_date    TEXT    NOT NULL,
            status      TEXT    NOT NULL DEFAULT 'open',
            locked_by   INTEGER,
            locked_at   TEXT,
            created_at  TEXT    NOT NULL DEFAULT (datetime('now'))
        );
CREATE TABLE credit_payments (
            id              INTEGER PRIMARY KEY AUTOINCREMENT,
            customer_id     INTEGER NOT NULL,
            invoice_id      TEXT,
            payment_date    TEXT    NOT NULL DEFAULT (date('now')),
            amount_halala   INTEGER NOT NULL,
            payment_method  TEXT    NOT NULL DEFAULT 'cash',
            reference_no    TEXT,
            notes           TEXT,
            created_by      INTEGER NOT NULL DEFAULT 1,
            created_at      TEXT    NOT NULL DEFAULT (datetime('now')),
            FOREIGN KEY (customer_id) REFERENCES customers(id)
        );
CREATE TABLE fixed_assets (
            id                      INTEGER PRIMARY KEY AUTOINCREMENT,
            asset_code              TEXT    NOT NULL UNIQUE,
            name                    TEXT    NOT NULL,
            category                TEXT    DEFAULT 'Equipment',
            purchase_date           TEXT    NOT NULL,
            purchase_cost_halala    INTEGER NOT NULL,
            residual_value_halala   INTEGER NOT NULL DEFAULT 0,
            useful_life_months      INTEGER NOT NULL DEFAULT 60,
            depreciation_method     TEXT    NOT NULL DEFAULT 'straight_line',
            accum_dep_halala        INTEGER NOT NULL DEFAULT 0,
            status                  TEXT    NOT NULL DEFAULT 'active',
            location                TEXT,
            serial_number           TEXT,
            notes                   TEXT,
            created_at              TEXT    NOT NULL DEFAULT (datetime('now')),
            created_by              INTEGER NOT NULL DEFAULT 1
        );
CREATE TABLE depreciation_runs (
            id              INTEGER PRIMARY KEY AUTOINCREMENT,
            run_date        TEXT    NOT NULL,
            asset_id        INTEGER NOT NULL,
            amount_halala   INTEGER NOT NULL,
            journal_entry_id INTEGER,
            created_at      TEXT    NOT NULL DEFAULT (datetime('now')),
            FOREIGN KEY (asset_id) REFERENCES fixed_assets(id)
        );
CREATE TABLE bank_accounts (
            id              INTEGER PRIMARY KEY AUTOINCREMENT,
            bank_name       TEXT    NOT NULL,
            account_number  TEXT,
            account_type    TEXT    DEFAULT 'current',
            currency        TEXT    DEFAULT 'SAR',
            current_balance_halala INTEGER DEFAULT 0,
            is_active       INTEGER DEFAULT 1,
            created_at      TEXT    NOT NULL DEFAULT (datetime('now'))
        );
CREATE TABLE bank_reconciliations (
            id              INTEGER PRIMARY KEY AUTOINCREMENT,
            bank_account_id INTEGER NOT NULL,
            period_start    TEXT    NOT NULL,
            period_end      TEXT    NOT NULL,
            statement_closing_halala INTEGER NOT NULL,
            system_balance_halala    INTEGER NOT NULL,
            difference_halala        INTEGER NOT NULL DEFAULT 0,
            status          TEXT    NOT NULL DEFAULT 'draft',
            notes           TEXT,
            created_at      TEXT    NOT NULL DEFAULT (datetime('now')),
            created_by      INTEGER NOT NULL DEFAULT 1,
            FOREIGN KEY (bank_account_id) REFERENCES bank_accounts(id)
        );
CREATE TABLE bank_rec_matches (
            id              INTEGER PRIMARY KEY AUTOINCREMENT,
            reconciliation_id INTEGER NOT NULL,
            journal_entry_line_id INTEGER,
            bank_statement_line TEXT,
            match_type      TEXT    DEFAULT 'matched',
            FOREIGN KEY (reconciliation_id) REFERENCES bank_reconciliations(id)
        );
CREATE TABLE prepaid_schedules (
            id              INTEGER PRIMARY KEY AUTOINCREMENT,
            description     TEXT    NOT NULL,
            total_amount_halala INTEGER NOT NULL,
            start_date      TEXT    NOT NULL,
            end_date        TEXT    NOT NULL,
            monthly_amount_halala INTEGER NOT NULL,
            expense_account_code INTEGER NOT NULL DEFAULT 5300,
            last_posted_date TEXT,
            is_active       INTEGER DEFAULT 1,
            created_at      TEXT    NOT NULL DEFAULT (datetime('now')),
            created_by      INTEGER NOT NULL DEFAULT 1
        );
CREATE TABLE recurring_expenses (
            id              INTEGER PRIMARY KEY AUTOINCREMENT,
            expense_name    TEXT    NOT NULL,
            amount_halala   INTEGER NOT NULL,
            account_code    INTEGER NOT NULL DEFAULT 5700,
            day_of_month    INTEGER NOT NULL DEFAULT 1,
            start_date      TEXT    NOT NULL,
            end_date        TEXT,
            last_posted_date TEXT,
            is_active       INTEGER DEFAULT 1,
            created_at      TEXT    NOT NULL DEFAULT (datetime('now')),
            created_by      INTEGER NOT NULL DEFAULT 1
        );
CREATE TABLE employees (
            id              INTEGER PRIMARY KEY AUTOINCREMENT,
            name            TEXT    NOT NULL,
            id_number       TEXT,
            nationality     TEXT    DEFAULT 'Saudi',
            job_title       TEXT,
            department      TEXT,
            basic_salary_halala     INTEGER NOT NULL DEFAULT 0,
            housing_allowance_halala INTEGER DEFAULT 0,
            transport_allowance_halala INTEGER DEFAULT 0,
            other_allowances_halala INTEGER DEFAULT 0,
            gosi_registered INTEGER DEFAULT 1,
            employment_date TEXT,
            bank_iban       TEXT,
            is_active       INTEGER DEFAULT 1,
            created_at      TEXT    NOT NULL DEFAULT (datetime('now')),
            created_by      INTEGER NOT NULL DEFAULT 1
        );
CREATE TABLE payroll_runs (
            id              INTEGER PRIMARY KEY AUTOINCREMENT,
            run_month       TEXT    NOT NULL,
            status          TEXT    NOT NULL DEFAULT 'draft',
            total_gross_halala    INTEGER DEFAULT 0,
            total_gosi_employee_halala INTEGER DEFAULT 0,
            total_gosi_employer_halala INTEGER DEFAULT 0,
            total_net_halala      INTEGER DEFAULT 0,
            journal_entry_id INTEGER,
            created_at      TEXT    NOT NULL DEFAULT (datetime('now')),
            created_by      INTEGER NOT NULL DEFAULT 1
        );
CREATE TABLE payroll_lines (
            id              INTEGER PRIMARY KEY AUTOINCREMENT,
            payroll_run_id  INTEGER NOT NULL,
            employee_id     INTEGER NOT NULL,
            gross_halala    INTEGER NOT NULL DEFAULT 0,
            gosi_employee_halala INTEGER NOT NULL DEFAULT 0,
            gosi_employer_halala INTEGER NOT NULL DEFAULT 0,
            other_deductions_halala INTEGER DEFAULT 0,
            net_halala      INTEGER NOT NULL DEFAULT 0,
            commissions_halala INTEGER DEFAULT 0,
            bonuses_halala  INTEGER DEFAULT 0,
            FOREIGN KEY (payroll_run_id) REFERENCES payroll_runs(id),
            FOREIGN KEY (employee_id)   REFERENCES employees(id)
        );
CREATE TABLE inventory_batches (
            id              INTEGER PRIMARY KEY AUTOINCREMENT,
            product_id      INTEGER NOT NULL,
            received_date   TEXT    NOT NULL,
            purchase_order_id INTEGER,
            quantity_received REAL  NOT NULL,
            quantity_remaining REAL NOT NULL,
            unit_cost_halala INTEGER NOT NULL,
            created_at      TEXT    NOT NULL DEFAULT (datetime('now')),
            FOREIGN KEY (product_id) REFERENCES products(id)
        );
CREATE TABLE stock_counts (
            id              INTEGER PRIMARY KEY AUTOINCREMENT,
            count_date      TEXT    NOT NULL,
            product_id      INTEGER NOT NULL,
            system_qty      REAL    NOT NULL,
            physical_qty    REAL    NOT NULL,
            difference      REAL    NOT NULL,
            reason          TEXT,
            journal_entry_id INTEGER,
            created_at      TEXT    NOT NULL DEFAULT (datetime('now')),
            created_by      INTEGER NOT NULL DEFAULT 1,
            FOREIGN KEY (product_id) REFERENCES products(id)
        );
CREATE TABLE budget_entries (
            id              INTEGER PRIMARY KEY AUTOINCREMENT,
            period          TEXT    NOT NULL,
            account_code    INTEGER NOT NULL,
            budgeted_halala INTEGER NOT NULL DEFAULT 0,
            created_at      TEXT    NOT NULL DEFAULT (datetime('now')),
            UNIQUE(period, account_code)
        );
CREATE TABLE cost_centres (
            id              INTEGER PRIMARY KEY AUTOINCREMENT,
            name            TEXT    NOT NULL UNIQUE,
            is_active       INTEGER DEFAULT 1,
            created_at      TEXT    NOT NULL DEFAULT (datetime('now'))
        );
CREATE TABLE label_templates (
            id TEXT PRIMARY KEY,
            name TEXT NOT NULL,
            category_id TEXT,
            config_json TEXT
        );
CREATE TABLE label_print_log (
            id TEXT PRIMARY KEY,
            product_id TEXT,
            timestamp INTEGER,
            copies INTEGER DEFAULT 1,
            label_key TEXT,
            status TEXT DEFAULT 'success',
            error TEXT
        );
CREATE TABLE deferred_revenue_schedules (
            id                      INTEGER PRIMARY KEY AUTOINCREMENT,
            description             TEXT    NOT NULL,
            total_amount_halala     INTEGER NOT NULL,
            start_date              TEXT    NOT NULL,
            end_date                TEXT    NOT NULL,
            monthly_amount_halala   INTEGER NOT NULL,
            liability_account_code  INTEGER NOT NULL DEFAULT 2500,
            revenue_account_code    INTEGER NOT NULL DEFAULT 4100,
            last_posted_date        TEXT,
            is_active               INTEGER DEFAULT 1,
            created_at              TEXT    NOT NULL DEFAULT (datetime('now')),
            created_by              INTEGER NOT NULL DEFAULT 1
        );
CREATE TABLE supplier_payments (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            supplier_id INTEGER NOT NULL,
            amount REAL NOT NULL,
            payment_date DATETIME DEFAULT CURRENT_TIMESTAMP,
            note TEXT,
            FOREIGN KEY (supplier_id) REFERENCES suppliers(id) ON DELETE CASCADE
        );
CREATE TABLE customer_payments (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            customer_id INTEGER NOT NULL,
            amount REAL NOT NULL,
            payment_date DATETIME DEFAULT CURRENT_TIMESTAMP,
            note TEXT,
            FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE CASCADE
        );
CREATE TABLE eosb_runs (
            id              INTEGER PRIMARY KEY AUTOINCREMENT,
            employee_id     INTEGER NOT NULL,
            run_date        TEXT    NOT NULL DEFAULT (date('now')),
            years_of_service REAL   NOT NULL,
            monthly_salary_halala INTEGER NOT NULL,
            eosb_halala     INTEGER NOT NULL,
            method          TEXT    NOT NULL DEFAULT 'saudi_labour_law',
            journal_entry_id INTEGER,
            created_at      TEXT    NOT NULL DEFAULT (datetime('now')),
            created_by      INTEGER NOT NULL DEFAULT 1
        );
CREATE TABLE wps_exports (
            id              INTEGER PRIMARY KEY AUTOINCREMENT,
            export_date     TEXT    NOT NULL DEFAULT (date('now')),
            payroll_run_id  INTEGER,
            file_path       TEXT,
            record_count    INTEGER DEFAULT 0,
            total_net_halala INTEGER DEFAULT 0,
            status          TEXT    NOT NULL DEFAULT 'generated',
            created_at      TEXT    NOT NULL DEFAULT (datetime('now'))
        );
CREATE TABLE bank_statement_imports (
            id              INTEGER PRIMARY KEY AUTOINCREMENT,
            bank_account_id INTEGER,
            import_date     TEXT    NOT NULL DEFAULT (date('now')),
            row_count       INTEGER DEFAULT 0,
            status          TEXT    NOT NULL DEFAULT 'pending',
            created_at      TEXT    NOT NULL DEFAULT (datetime('now'))
        );
CREATE TABLE bank_statement_lines (
            id              INTEGER PRIMARY KEY AUTOINCREMENT,
            import_id       INTEGER NOT NULL,
            bank_account_id INTEGER,
            transaction_date TEXT   NOT NULL,
            value_date      TEXT,
            description     TEXT,
            debit_halala    INTEGER DEFAULT 0,
            credit_halala   INTEGER DEFAULT 0,
            balance_halala  INTEGER DEFAULT 0,
            reference       TEXT,
            is_matched      INTEGER DEFAULT 0,
            journal_entry_line_id INTEGER,
            created_at      TEXT    NOT NULL DEFAULT (datetime('now')),
            FOREIGN KEY (import_id) REFERENCES bank_statement_imports(id)
        );
CREATE TABLE global_catalog (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            category TEXT,
            unit TEXT,
            barcode TEXT,
            default_price REAL DEFAULT 0,
            default_cost REAL DEFAULT 0
        );
CREATE TABLE zatca_invoices (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            icv INTEGER NOT NULL UNIQUE,
            invoice_hash TEXT NOT NULL,
            pih TEXT NOT NULL,
            invoice_uuid TEXT NOT NULL UNIQUE,
            invoice_type TEXT NOT NULL,
            submission_status TEXT NOT NULL DEFAULT 'pending',
            zatca_response TEXT,
            created_at TEXT NOT NULL DEFAULT (datetime('now'))
        );
CREATE TABLE zatca_device (
            id INTEGER PRIMARY KEY DEFAULT 1,
            private_key TEXT NOT NULL,
            csr TEXT NOT NULL,
            compliance_csid TEXT,
            compliance_rid TEXT,
            production_csid TEXT,
            environment TEXT NOT NULL DEFAULT 'sandbox',
            onboarding_complete INTEGER NOT NULL DEFAULT 0
        , cert_expires_at DATETIME, device_id TEXT, private_key_pem TEXT, current_icv INTEGER DEFAULT 0, last_pih TEXT, production_cert_pem TEXT, uuid TEXT, compliance_secret TEXT, production_secret TEXT, status TEXT, csr_pem TEXT, chain_generation INTEGER DEFAULT 1, recovery_migration_applied INTEGER DEFAULT 0, recovery_reason TEXT, recovery_timestamp TEXT, _backup_private_key_pem   TEXT, _backup_production_cert_pem TEXT, _backup_compliance_csid   TEXT, _backup_production_csid   TEXT, _backup_reset_at          TEXT);
CREATE TABLE zatca_queue (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            sale_id INTEGER NOT NULL,
            invoice_number TEXT NOT NULL,
            icv INTEGER NOT NULL,
            uuid TEXT NOT NULL,
            signed_xml TEXT NOT NULL,
            xml_hash TEXT NOT NULL,
            status TEXT DEFAULT 'pending',
            zatca_response_json TEXT,
            attempts INTEGER DEFAULT 0,
            created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
            submitted_at DATETIME, invoice_subtype TEXT DEFAULT '0200000', stamped_xml TEXT, has_warnings INTEGER DEFAULT 0, warning_messages TEXT,
            FOREIGN KEY (sale_id) REFERENCES sales(id)
        );
CREATE TABLE web_orders (
            id TEXT PRIMARY KEY,
            table_id INTEGER NOT NULL,
            items_json TEXT NOT NULL,
            server_total REAL NOT NULL,
            status TEXT DEFAULT 'pending',
            reject_reason TEXT,
            held_order_id INTEGER,
            idempotency_key TEXT UNIQUE,
            notes TEXT,
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL
        );
CREATE TABLE sponsor_organizations (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            default_discount REAL DEFAULT 100,
            cap_limit REAL DEFAULT 0,
            is_active INTEGER DEFAULT 1
        );
CREATE UNIQUE INDEX idx_sales_sync_id ON sales(sync_id);
CREATE UNIQUE INDEX idx_sales_items_sync_id ON sales_items(sync_id);
CREATE UNIQUE INDEX idx_held_orders_sync_id ON held_orders(sync_id);
CREATE UNIQUE INDEX idx_expenditures_sync_id ON expenditures(sync_id);
CREATE UNIQUE INDEX idx_shifts_sync_id ON shifts(sync_id);
CREATE UNIQUE INDEX idx_ledger_entries_sync_id ON ledger_entries(sync_id);
CREATE UNIQUE INDEX idx_staff_sync_id ON staff(sync_id);
CREATE UNIQUE INDEX idx_suppliers_sync_id ON suppliers(sync_id);
CREATE UNIQUE INDEX idx_purchase_orders_sync_id ON purchase_orders(sync_id);
CREATE UNIQUE INDEX idx_purchase_items_sync_id ON purchase_items(sync_id);
CREATE UNIQUE INDEX idx_products_sync_id ON products(sync_id);
