CREATE TRIGGER products_stock_integrity
        BEFORE UPDATE ON products
        FOR EACH ROW
        WHEN NEW.stock < 0
        BEGIN
            SELECT RAISE(ABORT, 'INSUFFICIENT_STOCK: Stock cannot be negative');
        END;
